update pages set contenu = '{"sections":[{"type":"heros","h1":"La maintenance industrielle à Nantes et dans l''estuaire","mecanisme":"Trois industries se partagent le bassin et n''ont rien en commun : l''aéronautique de la Basse-Loire, qui exige une traçabilité totale, le naval de Saint-Nazaire, qui vit de mécanique lourde et de soudure, et l''agroalimentaire du Grand Ouest, qui lave ses lignes tous les jours. Notre hub de techniciens de Nantes couvre les trois avec les mêmes techniciens évalués.","cta":"Faire chiffrer ma maintenance à Nantes","telephone":"04 78 33 72 05","phraseDelai":"Nous vous rappelons dans l''heure, du lundi au vendredi de 8h00 à 18h30. Astreinte 24/24 et 7/7 en option, nuits, week-ends et jours fériés."},{"type":"chiffres","chiffres":[{"valeur":"+ 120","libelle":"clients industriels accompagnés, dont plus de 80 réguliers"},{"valeur":"10 %","libelle":"des candidats retenus, entretien technique et comportemental, résultats partagés"},{"valeur":"10","libelle":"hubs de techniciens en France, dont un à Nantes, plus notre siège lyonnais et nos agences de Montréal, Dubaï et Madrid"}]},{"type":"probleme","punchline":"Votre ligne de conditionnement s''arrête après le lavage du soir, et le seul technicien qui la connaît est en congé jusqu''à lundi. Dans le Grand Ouest, la compétence rare est plus difficile à remplacer que la pièce.","puces":[{"accroche":"Le lavage intensif use les équipements plus vite.","texte":"Agroalimentaire du Grand Ouest : eau, soude, températures, et des roulements qui ne tiennent pas les durées théoriques."},{"accroche":"L''aéronautique ne tolère aucun trou documentaire.","texte":"Un contrôle manqué vaut un arrêt, même quand la machine fonctionne."},{"accroche":"Le naval travaille sur des pièces qui ne passent pas la porte.","texte":"Reprise sur site, soudure, chaudronnerie : l''atelier vient à la pièce, pas l''inverse."},{"accroche":"Le bassin est étendu, la compétence concentrée.","texte":"Entre l''estuaire, le vignoble et la Vendée, trouver un automaticien disponible prend plus de temps que réparer."},{"accroche":"Un prestataire local seul plafonne vite.","texte":"Le jour où le défaut sort de sa spécialité, il sous-traite, et vous perdez le fil."}]},{"type":"offre","lignes":[{"prestation":{"accroche":"Des gammes adaptées au lavage intensif","texte":"points de contrôle, étanchéité, protection des moteurs, éléments d''usure suivis."},"benefice":"Vos lignes agroalimentaires tiennent les cadences sans réparations à répétition."},{"prestation":{"accroche":"Une qualité documentaire au niveau des donneurs d''ordre aéronautiques","texte":"traçabilité, historique par équipement, pièces référencées."},"benefice":"Vos audits passent sans course aux justificatifs."},{"prestation":{"accroche":"Soudure et chaudronnerie sur site","texte":"reprise de bâtis, tuyauterie, réparations d''urgence."},"benefice":"Une pièce lourde se répare où elle est, sans démontage complet ni transport."},{"prestation":{"accroche":"Le champ technique complet","texte":"[mécanique](/expertises/mecanique/), [électricité](/expertises/electrique/), [électromécanique](/expertises/electromecanique/), [automatisme](/expertises/automatisme/), [hydraulique](/expertises/hydraulique/), [pneumatique](/expertises/pneumatique/), [soudure](/expertises/soudure/)."},"benefice":"Un seul contrat pour un parc qui mélange toujours plusieurs technologies."},{"prestation":{"accroche":"Astreinte 24/24 et 7/7 en option","texte":"pour les sites en continu."},"benefice":"Une panne du dimanche soir ne devient pas un lundi matin sacrifié."},{"prestation":{"accroche":"Relais du Grand Ouest","texte":"[Loire-Atlantique](/implantations/nantes/loire-atlantique/), [Rennes](/implantations/nantes/rennes/), [Brest](/implantations/nantes/brest/)."},"benefice":"Un industriel réparti entre Bretagne et Pays de la Loire garde un seul interlocuteur."}],"prose":[{"texte":"Le secteur le plus représenté de la région a sa page dédiée : [maintenance industrielle agroalimentaire](/secteurs/agroalimentaire/), hygiène et redémarrage propre compris."}]},{"type":"deroule","etapes":[{"titre":"Vous décrivez la situation","texte":"Panne bloquante, dérive d''équipement ou retard de préventif, au 04 78 33 72 05 ou par le formulaire."},{"titre":"Rappel dans l''heure","texte":"Aux horaires ouvrés, un chargé d''affaires qualifie la machine, l''accès, les habilitations et les pièces pressenties. Vous savez rapidement si nous avons le technicien, et lequel."},{"titre":"La préparation","texte":"Brief technique, consignes de sécurité du site, accueil sécurité, plan de prévention. Rien n''est découvert sur place."},{"titre":"L''intervention","texte":"Mesures, contrôles, diagnostic, réparation, essais, remise en cadence avec vos opérateurs."},{"titre":"Le compte rendu","texte":"Causes, actions, pièces, préconisations, versés dans votre GMAO, avec ce que le premier niveau doit surveiller ensuite."},{"titre":"Le point périodique","texte":"Disponibilité, récurrence par équipement, retard de préventif résorbé. Les chiffres décident de la suite."}]},{"type":"garanties","puces":[{"accroche":"La même équipe dans la durée","texte":"pas de personne différente à chaque visite. Sur un contrat suivi, l''intervenant qui connaît vos machines revient, et l''historique reste sur le site."},{"accroche":"Une compétence vérifiée avant l''arrivée","texte":"entretien technique et comportemental, 10 % des candidats retenus, résultats d''évaluation présentés avant la première intervention."},{"accroche":"Un refus net plutôt qu''un dépannage raté","texte":"si un matériel sort de notre périmètre, nous le disons au premier échange. Le périmètre couvert est écrit au devis."}]},{"type":"cta","question":"Besoin de sécuriser une ligne que seule une personne sait dépanner ?","bouton":"Faire chiffrer ma maintenance à Nantes","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."},{"type":"preuves","preuves":[{"titre":"1 à 3 techniciens en renfort permanent sur plusieurs sites de production","texte":", confort thermique, depuis octobre 2024","lienLibelle":"Étude de cas GROUPE ATLANTIC : renfort d''équipes","lienHref":"/preuves/groupe-atlantic/"},{"titre":"Deux techniciens en 3x8 sur les lignes liquides et poudre","texte":"d''un site agroalimentaire","lienLibelle":"Étude de cas DANONE : lignes de production","lienHref":"/preuves/danone-lignes-de-production/"},{"titre":"Un responsable maintenance intégré sur site pendant une montée de cadence","texte":"troisième trimestre 2025, reporting à la direction industrielle","lienLibelle":"Étude de cas ERIKS","lienHref":"/preuves/eriks/"},{"titre":"Renfort de contrôle de chantier chez un spécialiste de l''automatisation logistique","texte":"intervenants intégrés aux équipes sur des projets stratégiques","lienLibelle":"Étude de cas ALSTEF Group : collaboration","lienHref":"/preuves/alstef-group/"},{"titre":"Montages, déplacements de machines et renfort technique ponctuel","texte":"chez un acteur de l''étanchéité et de l''isolation, sur l''année 2025","lienLibelle":"Étude de cas SOPREMA : travaux ponctuels","lienHref":"/preuves/soprema/"}]},{"type":"objections","questions":[{"question":"Êtes-vous vraiment implantés à Nantes ?","reponse":"Oui. Nantes est l''un de nos 10 hubs de techniciens en France : des techniciens basés sur le bassin, pas une équipe envoyée de loin. S''y ajoutent notre siège lyonnais et nos agences de Montréal, Dubaï et Madrid pour les compétences rares."},{"question":"Couvrez-vous toute la Loire-Atlantique et le Grand Ouest ?","reponse":"Oui. Nos techniciens basés à Nantes couvrent la métropole nantaise, l''estuaire jusqu''à Saint-Nazaire, le vignoble, le pays de Grand-Lieu et le nord du département. Au-delà, elles interviennent vers Rennes, Brest, Angers et la Vendée, avec le renfort des autres hubs de techniciens et du siège lyonnais quand une compétence rare est requise."},{"question":"Intervenez-vous en zone sous sas d''hygiène ?","reponse":"Oui. Tenues, procédures d''entrée, nettoyage des outils, redémarrage propre : les règles du site s''appliquent à nos techniciens comme à vos équipes. Les opérations lourdes se planifient après lavage ou pendant l''arrêt programmé, jamais au milieu d''une production."},{"question":"Quel délai pour une intervention à Nantes ?","reponse":"Nous ne promettons pas un chiffre : la distance, l''accès et la pièce en cause changent tout. L''engagement tenu est le rappel dans l''heure aux horaires ouvrés, un technicien briefé qui n''arrive pas en découverte, et l''astreinte 24/24 et 7/7 en option pour les nuits et les week-ends."},{"question":"Combien coûte un contrat de maintenance ?","reponse":"Zéro arrêt commence à sur devis, trois niveaux de couverture, engagement type de 6 mois renouvelable. Le chiffrage suit votre parc, vos fréquences de visite et l''astreinte retenue, après un état des lieux mené sur le terrain. Le diagnostic de départ ne vous est pas facturé."},{"question":"Pouvez-vous tenir un poste à temps plein dans notre usine ?","reponse":"Oui, c''est l''offre [Résidence](/offres/residence/) : un technicien salarié Migen intégré à votre équipe, encadré par un référent, prise de poste en 2 à 3 semaines et remplacement assuré en cas d''absence. La même personne vous suit dans la durée, et votre entreprise garde l''historique de ses machines."},{"question":"Travaillez-vous avec les PME ou seulement les grands groupes ?","reponse":"Les deux. Une PME de mécanique a les mêmes pannes qu''un grand groupe avec moins de ressources pour les absorber. Les formats vont de l''intervention unique à quelques visites par an ou au contrat complet, dimensionnés sur le besoin réel."}]},{"type":"ctaFinal","question":"Besoin d''un mainteneur qui tienne l''aéronautique, le naval et l''agroalimentaire ?","bouton":"Faire chiffrer ma maintenance à Nantes","rappel":"ou appelez le 04 78 33 72 05, rappel dans l''heure aux horaires ouvrés."}]}'::jsonb where path = '/implantations/nantes/';
